def count_pairs(n):
    if n < 1:
        return 0

    # 2023 = 7 * 17^2
    # Let K = n! / 2023
    # We need to find the number of distinct prime factors of K.
    # K is an integer if v_p(n!) >= v_p(2023) for all p.
    # v_p(2023) is:
    # v_7(2023) = 1
    # v_17(2023) = 2
    # v_p(2023) = 0 otherwise.

    # Check if K is an integer
    # v_p(n!) = floor(n/p) + floor(n/p^2) + ...
    def get_vp(n, p):
        count = 0
        while n > 0:
            count += n // p
            n //= p
        return count

    if get_vp(n, 7) < 1 or get_vp(n, 17) < 2:
        return 0 # No such pairs (a, b) exist

    # K = n! / (7 * 17^2)
    # Prime factors of K are all primes p <= n such that v_p(n!) - v_p(2023) > 0.
    factors = 0

    # Find all primes p <= n
    primes = []
    is_prime = [True] * (n + 1)
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False

    for p in primes:
        vp_n_fact = get_vp(n, p)
        vp_2023 = 0
        if p == 7:
            vp_2023 = 1
        elif p == 17:
            vp_2023 = 2

        if vp_n_fact > vp_2023:
            factors += 1

    return 2**factors

